import type { NextConfig } from "next"
import { readFileSync, existsSync } from "node:fs"
import { join } from "node:path"

/** 301 redirects from every Wix product URL, generated by the catalog migration (scripts output). */
function wixRedirects(): { source: string; destination: string; permanent: boolean }[] {
  const file = join(process.cwd(), "redirects.json")
  if (!existsSync(file)) return []
  const rows = JSON.parse(readFileSync(file, "utf8")) as { from: string; to: string }[]
  return rows.map((r) => ({ source: r.from, destination: r.to, permanent: true }))
}

const backend = new URL(process.env.NEXT_PUBLIC_MEDUSA_BACKEND_URL ?? "http://localhost:9000")

const config: NextConfig = {
  poweredByHeader: false,
  reactStrictMode: true,
  transpilePackages: ["@haanta/ui"],
  images: {
    formats: ["image/avif", "image/webp"],
    remotePatterns: [
      { protocol: "https", hostname: "res.cloudinary.com" },
      { protocol: "https", hostname: "static.wixstatic.com", pathname: "/media/**" },
      { protocol: "https", hostname: "cdn.sanity.io" },
      { protocol: backend.protocol.replace(":", "") as "http" | "https", hostname: backend.hostname, port: backend.port, pathname: "/static/**" },
    ],
  },
  async redirects() {
    return [
      ...wixRedirects(),
      // Legacy Wix paths
      { source: "/shop-all", destination: "/shop", permanent: true },
      { source: "/shipped-from-us", destination: "/shop?ships_from=houston", permanent: true },
    ]
  },
}

export default config
